<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import DataList from '../components/DataList.vue';
import { apiRequest, unwrap, type ApiEnvelope } from '../lib/api';

const route = useRoute();
const report = ref<Record<string, unknown>>({});
const loading = ref(true);
const error = ref('');
const filter = ref<'all' | 'failed' | 'passed'>('all');
const selectedId = ref('');
const results = computed(() => Array.isArray(report.value.results) ? report.value.results as Record<string, unknown>[] : []);
const visible = computed(() => results.value.filter(item => filter.value === 'all' || Boolean(item.passed) === (filter.value === 'passed')));
const selected = computed(() => visible.value.find(item => item.id === selectedId.value) || visible.value[0] || null);
async function load() {
  loading.value = true; error.value = '';
  try { report.value = unwrap(await apiRequest<ApiEnvelope<Record<string, unknown>>>(`/api/evals/runs/${encodeURIComponent(String(route.params.runId || ''))}`)); if (!results.value.some(item => item.id === selectedId.value)) selectedId.value = String(results.value[0]?.id || ''); }
  catch (cause) { error.value = cause instanceof Error ? cause.message : '评测报告读取失败'; }
  finally { loading.value = false; }
}
watch(() => route.params.runId, load);
onMounted(load);
</script>

<template>
  <main class="workspace-main eval-run-page"><div class="breadcrumb"><RouterLink to="/eval-platform">评测平台</RouterLink>　/　运行报告</div><div class="eval-run-heading"><div><div class="eyebrow">EVALUATION RUN</div><h1>评测报告</h1><p>运行 ID：{{ route.params.runId }}</p></div><button class="secondary-button" @click="load">刷新报告</button></div><p v-if="error" class="inline-error" role="alert">{{ error }}</p><p v-if="loading" class="loading-state">正在读取…</p><template v-else><div class="eval-run-summary"><div><span>整体结果</span><strong>{{ report.passed ? '通过' : '未通过' }}</strong></div><div><span>通过率</span><strong>{{ report.passRate ?? 0 }}%</strong></div><div><span>通过 / 总数</span><strong>{{ report.passedCount ?? 0 }} / {{ report.total ?? 0 }}</strong></div><div><span>平均分</span><strong>{{ report.averageScore ?? '—' }}</strong></div></div><section class="paper-panel eval-run-overview"><div class="panel-heading"><strong>这次评测检查了什么</strong><span>{{ report.createdAt ? new Date(String(report.createdAt)).toLocaleString('zh-CN') : '' }}</span></div><p>逐项查看哪些问题通过、哪些问题失败，再沿验证检查和数据产物追原因。</p><DataList :value="report.metadata || {}" :limit="8" /></section><div class="eval-run-layout"><section class="paper-panel eval-run-cases"><div class="panel-heading"><strong>评测用例</strong><span>{{ visible.length }} 项</span></div><div class="eval-run-filters"><button v-for="item in [{id:'all',label:'全部'},{id:'failed',label:'未通过'},{id:'passed',label:'已通过'}]" :key="item.id" :class="{active:filter === item.id}" @click="filter = item.id as typeof filter">{{ item.label }}</button></div><button v-for="item in visible" :key="String(item.id)" :class="['eval-run-case',{active:selected?.id===item.id}]" @click="selectedId = String(item.id)"><span :class="item.passed ? 'passed' : 'failed'">{{ item.passed ? '通过' : '失败' }}</span><strong>{{ item.name || item.id }}</strong><small>{{ item.capabilityLabel || item.capabilityId }} · 评分 {{ item.score ?? '—' }}</small></button><p v-if="!visible.length" class="eval-empty">当前筛选下没有用例。</p></section><article v-if="selected" class="paper-panel eval-run-detail"><div class="panel-heading"><strong>{{ selected.name || selected.id }}</strong><span :class="selected.passed ? 'passed' : 'failed'">{{ selected.passed ? '通过' : '未通过' }}</span></div><p class="eval-question">{{ selected.question }}</p><div class="eval-run-facts"><div><strong>{{ selected.score ?? '—' }}</strong><span>评分</span></div><div><strong>{{ selected.durationMs == null ? '—' : `${Math.round(Number(selected.durationMs) / 1000)} 秒` }}</strong><span>耗时</span></div><div><strong>{{ selected.validationStatus || '—' }}</strong><span>验证状态</span></div></div><section v-if="Array.isArray(selected.failures) && selected.failures.length"><h3>失败原因</h3><ul><li v-for="(reason,index) in selected.failures" :key="index">{{ reason }}</li></ul></section><section><h3>验证检查</h3><DataList :value="selected.validationChecks || []" :limit="30" /></section><section><h3>数据与产物</h3><DataList :value="selected.artifacts || {}" :limit="20" /></section><section><h3>执行与质量</h3><DataList :value="selected.agentExecution || selected.evaluation || {}" :limit="15" /></section><RouterLink v-if="selected.projectId" class="secondary-button" :to="`/${selected.projectId}/chat`">打开对应研究任务 →</RouterLink></article></div></template>
  </main>
</template>

<style scoped>.eval-run-page{max-width:1200px;margin:auto}.eval-run-heading{display:flex;justify-content:space-between;align-items:center;gap:14px}.eval-run-page h1{font:650 34px Georgia,'Noto Serif SC',serif;margin:10px 0}.eval-run-page p{font-size:13px;color:var(--muted);line-height:1.7}.eval-run-page .paper-panel{padding:20px}.eval-run-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:19px 0}.eval-run-summary>div{background:#263d33;color:white;border-radius:7px;padding:16px}.eval-run-summary span,.eval-run-summary strong{display:block}.eval-run-summary span{color:#d3c5a5;font-size:11px}.eval-run-summary strong{font-size:23px;margin-top:7px}.eval-run-overview{margin:13px 0}.eval-run-layout{display:grid;grid-template-columns:minmax(230px,320px) minmax(0,1fr);gap:14px;align-items:start}.eval-run-filters{display:flex;gap:5px;margin:10px 0}.eval-run-filters button{border:1px solid #dcded4;background:#f7f5ef;border-radius:5px;padding:6px 9px;font-size:11px}.eval-run-filters button.active{background:#a56e27;color:white}.eval-run-case{display:grid;gap:6px;width:100%;text-align:left;border:0;border-top:1px solid #e1e3d8;background:transparent;padding:12px}.eval-run-case.active{background:#f7f1e7}.eval-run-case span,.eval-run-detail .panel-heading span{font-size:11px;font-weight:700}.passed{color:#287455}.failed{color:#ad4d3e}.eval-run-case strong{font-size:13px}.eval-run-case small{font-size:11px;color:#69736b}.eval-question{background:#f4f1e9;border-left:3px solid #ad772f;padding:12px}.eval-run-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.eval-run-facts div{background:#f4f1e9;padding:12px}.eval-run-facts strong,.eval-run-facts span{display:block}.eval-run-facts strong{font-size:17px}.eval-run-facts span{font-size:10px;color:#69736b}.eval-run-detail section{margin:20px 0}.eval-run-detail h3{font-size:14px;border-bottom:1px solid #e1e3d8;padding-bottom:7px}.eval-run-detail li{font-size:12px;line-height:1.7;margin:5px 0}.eval-empty{padding:16px}@media(max-width:760px){.eval-run-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.eval-run-layout{grid-template-columns:1fr}}</style>
